def close(self) -> None:
    # Let workers drain their queues before stopping the commit loop.
    for work_queue in self.queue_pool.queues:
        work_queue.shutdown(immediate=False)
    for worker in self.queue_pool.workers:
        worker.join()
    self.queue_pool.shutdown()

    self.shutdown_event.set()
    # Ensure no background commit can race with the final commit.
    self.commit_thread.join()
    try:
        committable = self.queue_pool.offset_tracker.get_committable_offsets()
        if committable:
            metrics.incr(
                "remote_subscriptions.queue_pool.offsets_committed",
                len(committable),
                tags={"identifier": self.queue_pool.identifier},
            )
            self.commit_function(committable)
            for partition, offset in committable.items():
